// One Slack message listing the new jobs, grouped by company. No new job: no message.
const jobs = $input.all().map((i) => i.json).filter((j) => j.found !== false);
if (jobs.length === 0) return [];
const byCompany = {};
for (const j of jobs) (byCompany[j.company] ??= []).push(j);
const clean = (t) => (t ?? '').replace(/[<>|]/g, ' ').slice(0, 120);
const blocks = Object.entries(byCompany).slice(0, 20).map(([company, list]) => {
  const lines = list.slice(0, 10).map((j) => `• <${j.jobUrl}|${clean(j.title)}>${j.department ? ` (${clean(j.department)})` : ''}, ${clean(j.location) || 'location n/a'}`);
  if (list.length > 10) lines.push(`…and ${list.length - 10} more`);
  return `*${clean(company)}*: ${list.length} new job${list.length > 1 ? 's' : ''}\n${lines.join('\n')}`;
});
return [{ json: { text: `:briefcase: *New jobs at your target companies*\n\n${blocks.join('\n\n')}`, newJobs: jobs.length } }];
